UPDATE weapon_dictionary SET description='2K12 Kub은 소련이 개발한 궤도형 중거리 지대공미사일 체계로 NATO 명칭은 SA-6 Gainful이다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='2k12-kub';
UPDATE weapon_dictionary SET description='2S1 Gvozdika는 소련이 1972년 도입한 122mm 궤도형 자주포로, 2A18 곡사포를 MT-LBu 계열 차체에 올렸다.', specs='{"crew":4,"widthM":2.85,"caliber":"122mm","lengthM":7.26,"rangeKm":15.3,"weightT":16,"armament":"2A18 122mm","speedKmh":60,"propulsion":"YaMZ-238N 220kW"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='2s1-gvozdika';
UPDATE weapon_dictionary SET description='2S19 Msta-S는 소련이 설계한 152mm 궤도형 자주포로, 1989년 소련군에 채택되어 러시아군에 취역했다. 주포는 바리카디가 만든 152mm 2A64이고 OF-45 고폭탄 사거리는 24.7km다. 전투중량 42톤, 승무원 5명, 도로 속도 시속 60km, 전장 7.15m이며 차체는 T-80 현가장치와 T-72 동력장치를 쓴다.', specs='{"crew":5,"widthM":3.38,"caliber":"152mm","heightM":2.99,"lengthM":7.15,"rangeKm":24.7,"weightT":42,"armament":"152mm 2A64, 12.7mm NSVT","speedKmh":60}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='2s19-msta-s';
