UPDATE weapon_dictionary SET description='A26형은 사브 코쿰스가 설계하는 스웨덴의 재래식 잠수함으로, 스웨덴 해군용 함명은 블레킹에급이다. FMV는 스웨덴용 2척 계약을 적고 길이 66.1 m, 수상 배수량 1925톤, 디젤 3기와 스털링 3기, 승조원 17명에서 26명에 최대 35명, 어뢰와 기뢰, ROV, 직경 1.5 m 유연탑재구를 제시한다. 사브는 2026년 6월 29일 폴란드와 A26 3척 및 무장, 훈련, 지원 패키지 계약을 맺었고 최종 인도는 2038년으로 적었다. 배수량 1925톤은 FMV가 수상 배수량으로 적은 값이다.', specs='{"lengthM":66.1,"armament":"어뢰, 기뢰, ROV, MSF, 직경 1.5 m Flexible Payload Lock","propulsion":"디젤 3기, 스털링 3기","displacementT":1925,"crew":17}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='a26';
