UPDATE weapon_dictionary SET description='AS90은 BAE Systems Land Systems가 배로인퍼니스에서 생산한 영국 육군 155mm 궤도형 자주포로 1992년 취역했다. 영국 육군용으로 179문이 제작되었고 39구경 또는 52구경 포신을 쓴다. 일반탄 사거리는 24.7km, 보조추진탄은 30km이며 52구경 포신에서는 40km를 넘는다. 영국 국방부는 2023년 AS90을 우크라이나에 현물로 공여했다.', specs='{"caliber":"155mm/39","rangeKm":24.7,"armament":"155mm 39구경 또는 52구경","propulsion":"Cummins 660hp V8 디젤"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='as-90';
UPDATE weapon_dictionary SET description='레드백은 한화가 한국 K21을 바탕으로 개량한 궤도형 보병전투차로, 호주 LAND 400 3단계에서 라인메탈 KF41 Lynx를 제치고 선정되었다. 디펜스 뉴스는 2023년 7월 호주가 국내에서 129대를 만들며 추정 비용은 50억에서 70억 호주달러이고, 초도 인도는 2027년, 완료는 2028년 말로 앞당긴다고 전한다. 같은 기사는 개량 장갑, 부시마스터 30mm 포, 엘비트 스파이크 LR, 수시 일체형 고무 궤도를 적용한다.', specs='{"armament":"Bushmaster 30mm, Elbit Spike LR","caliber":30}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='as21-redback';
