UPDATE weapon_dictionary SET description='Borsuk는 폴란드 무장청이 2025년 3월 27일 PGZ와 후타 스탈로바 볼라 컨소시엄에 111대를 발주한 궤도형 보병전투차다. 폴란드 국방부는 계약 금액을 약 65억 7,000만 즈워티로, 인도 기간을 2025년부터 2029년이다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='borsuk';
