UPDATE weapon_dictionary SET description='충남급은 한국 해군의 울산급 Batch-III 호위함이다. 한국일보는 3번함 전남함이 2025년 11월 25일 SK오션플랜트에서 진수됐고, 3,600톤급에 전장 129m, 폭 14.8m, 높이 38.9m라고 전한다. 해군은 1번함을 충남함, 2번함을 경북함으로 부르며, 전남함은 2026년 말 인도를 계획한다. 추진은 대구급과 같은 하이브리드이고, 초도함 취역 연도는 이 기사에 없다.', specs='{"beamM":14.8,"lengthM":129,"armament":"5인치 함포, KVLS, 대함유도탄방어유도탄, 함대함유도탄, 전술함대지유도탄, 장거리 대잠어뢰","propulsion":"대구급과 같은 하이브리드 추진","displacementT":3600,"widthM":14.8,"heightM":38.9}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='chungnam-class';
UPDATE weapon_dictionary SET description='콜린스급은 스웨덴 Kockums의 Type 471 설계를 바탕으로 호주 ASC가 사우스오스트레일리아에서 건조한 재래식 디젤-전기 잠수함이다. ASC이다.', specs='{"crew":42,"lengthM":78,"armament":"함수 어뢰발사관 6문, Mk48 중어뢰 또는 서브하푼 최대 22기, 기뢰 최대 44발","propulsion":"Diesel-electric","displacementT":3000,"torpedoTubes":6}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='collins-class';
