UPDATE weapon_dictionary SET description='대구급은 한국 해군의 호위함으로 FFX Batch-II이며, 한화오션(구 DSME)과 HHI가 공동 설계하고 8척을 건조했다. 만재 배수량 2,800톤, 전장 122m, 폭 14m, 높이 35m, 속력 30노트이고 헬기 1대를 탑재한다. 같은 기사는 추진을 CODLOG라고 하면서 가스터빈과 전기추진모터를 동시에 쓰는 하이브리드라고도이다.', specs='{"beamM":14,"lengthM":122,"speedKt":30,"aircraft":"헬기 1대","armament":"KVLS 16셀(해궁, 홍상어), SSM-700K 해성, 127mm Mk 45 Mod 4, Phalanx Block 1B","propulsion":"기사는 CODLOG로 적고, 가스터빈과 전기추진모터를 동시에 쓰는 하이브리드라고도 적음","displacementT":2800,"widthM":14,"heightM":35}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='daegu-class';
UPDATE weapon_dictionary SET description='vz.77 DANA는 체코슬로바키아가 Tatra 815 8x8 차체에 올린 152mm 차륜형 자주포다. STV GROUP은 총중량 29.25톤, 승무원 4+1명, 엔진 Tatra 3-920.52 V-12, 도로 속도 시속 80km, 항속거리 최대 740km, 크기 11.156m x 3.000m x 3.350m를 제시한다.', specs='{"crew":"4+1","widthM":3,"caliber":"152mm","heightM":3.35,"lengthM":11.156,"rangeKm":20,"weightT":29.25,"armament":"152mm, 12.7mm DShK","speedKmh":80,"propulsion":"Tatra 3-920.52 V-12"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='dana';
