UPDATE weapon_dictionary SET description='Bonifaz급 F-110은 스페인 해군이 도입 중인 차세대 호위함이다. 해군은 다섯 척의 함명을 지정했으며, 2024년 공식이다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='f110-bonifaz-class';
UPDATE weapon_dictionary SET description='F125 바덴뷔르템베르크급은 독일 해군의 안정화 작전용 호위함으로, 네 척이 취역했다. 건조는 thyssenkrupp Marine Systems를 주관사로 한 ARGE F125가 맡았고 Lürssen이 참여했다. 선도함 Baden-Württemberg는 2019년 6월 17일, Nordrhein-Westfalen은 2020년 6월 10일, Sachsen-Anhalt는 2021년 5월 17일, Rheinland-Pfalz는 2022년 7월 13일 취역했다.', specs='{"crew":126,"beamM":18.8,"speed":"26노트 초과","lengthM":149.5,"aircraft":"Sea Lynx Mk88A 2기","armament":"127mm Lightweight LCG, 27mm MLG 2문, 12.7mm HITROLE 5문, RGM-84 Harpoon 발사대 2기, RIM-116 RAM 발사대 2기, MASS 4기","draughtM":5.4,"propulsion":"CODLAG, 가스터빈 1기(20,000kW), 디젤 발전기 4기, 전기추진모터 2기(각 4,500kW), 선수 스러스터, 가변피치 프로펠러 2축, 총출력 29,000kW","displacementT":7200,"additionalCrew":70,"widthM":18.8,"speedKt":26}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='f125';
