UPDATE weapon_dictionary SET description='핼리팩스급은 캐나다 해군의 다목적 초계 호위함이다. 해군 함급 페이지는 12척을 올리며, 선도함 HMCS Halifax는 1992년 6월 29일 취역했다. 같은 해군 사료는 HMCS St. John''s의 건조자를 Saint John Dry Dock and Shipbuilding Co. Ltd.', specs='{"crew":225,"beamM":16.4,"lengthM":134.1,"rangeNm":9500,"speedKt":30,"aircraft":"CH-148 Cyclone","armament":"하푼 함대함미사일, Evolved Sea Sparrow, Bofors 57mm Mk 3 함포, 20mm Phalanx CIWS, 원격무장 4기, 대잠 유도어뢰, MASS 소프트킬","displacementT":4770}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='halifax-class';
