UPDATE weapon_dictionary SET description='헌터급은 BAE Systems Type 26을 개량한 호주 해군의 유도탄 호위함(FFG)으로, BAE Systems Maritime Australia가 남호주 Osborne에서 6척을 건조한다. 2024년 9월 기준 경하 배수량은 약 8,200톤이고 전장 151.4m, 폭 20.8m, CODLOG 추진, 최고 속력 27노트 초과, 전기추진 항속거리 7,000해리다. 승조원은 탑재 헬기 인원을 포함해 183명이고 수용 인원은 208명이며 MH-60R 1대를 운용한다. 전력화는 2030년대 초로 예정돼 아직 취역하지 않았다.', specs='{"crew":183,"beamM":20.8,"speed":"27노트 초과","lengthM":151.4,"rangeNm":7000,"aircraft":"MH-60R 1대","armament":"Mk 45 Mod 4 5인치포, SM-2, ESSM, 대함미사일, Mk 41 수직발사대, MU90 및 Mk 54 공중발사 어뢰, Nulka, 함정 어뢰방어, AGM-114N Hellfire, APKWS","propulsion":"CODLOG","accommodation":208,"displacementT":8200,"widthM":20.8,"speedKt":27}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='hunter-class';
