UPDATE weapon_dictionary SET description='K21은 두산 DST가 한국 육군의 K200 계열을 대체하려고 개발한 수륙양용 궤도형 보병전투차로, 포탑에 40mm 기관포를 단다.', specs='{"crew":3,"widthM":3.4,"heightM":2.6,"lengthM":6.9,"rangeKm":450,"armament":"40mm 기관포, 대전차유도탄 2기, 7.62mm 동축 기관총","speedKmh":70,"passengers":9,"propulsion":"Doosan D2840LXE V-10 터보 디젤 750hp. 성능개량형은 840hp","waterSpeedKmh":6,"weightExclCombatT":25,"caliber":40}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='k21';
UPDATE weapon_dictionary SET description='K239 천무는 한화에어로스페이스의 한국형 8륜 다연장로켓이고, CGR-080은 별도 발사대가 아니라 사거리 80km, CEP 15m의 239mm GPS/INS 유도로켓으로 폴란드형 Homar-K의 핵심 탄약이다.', specs='{"cgr080":"239mm GPS/INS, 사거리 80km, CEP 15m","chassis":"8x8","missileTypes":"CGR-080, CTM-MR, CTM-290","maxMissileRangeKm":"노르웨이 계약 기준 최대 500","rangeKm":80}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='k239-chunmoo';
UPDATE weapon_dictionary SET description='K9 Thunder는 삼성테크윈이 개발하고 현재 한화에어로스페이스 이름으로 소개되는 155mm 52구경 궤도형 자주포로, 1999년 본격 양산에 들어갔다. 전투중량 46.3톤, 승무원 5명, 도로 속도 시속 67km이며 표준 고폭탄 사거리는 30km, 로켓보조탄은 40km다. 탄약보급차 K10이 같은 계열로 함께 소개되고, 확인된 파생형에는 K9A1, K9 Vajra-T, AS9 Huntsman, K9FIN, VIDAR, K9A1EGY가 있다.', specs='{"crew":5,"widthM":3.4,"caliber":"155mm/52","heightM":2.73,"lengthM":7.44,"rangeKm":40,"weightT":46.3,"armament":"155mm/52, 12.7mm M2","speedKmh":67,"propulsion":"MTU MT 881 Ka-500 1,000hp"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='k9-thunder';
