UPDATE weapon_dictionary SET description='도산안창호급은 방위사업청이 2007년 착수한 장보고-III 사업으로 국내에서 개발한 재래식 잠수함이다. 2021년 정책브리핑은 도산안창호함이 시험평가를 마치고 해군에 인도됐으며 국산 연료전지를 탑재했다.', specs='{"propulsion":"배치-II 리튬전지체계","displacementT":3600}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='kss-iii';
