UPDATE weapon_dictionary SET description='LAROM은 루마니아가 이스라엘과 협력해 만든 차륜형 다연장로켓이다.', specs='{"crew":4,"load":"포드 2개. 122mm 40발 또는 160mm 26발","widthM":2.4,"caliber":"122mm 또는 160mm","heightM":3.1,"lengthM":7.35,"weightT":13.7,"engineHp":410,"quantity":54,"gradRangeKm":"약 20","larMk4RangeKm":"10-45"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='larom';
UPDATE weapon_dictionary SET description='General Dynamics Land Systems가 개발한 8×8 차륜형 장갑차 계열이다. 보병수송·정찰·지휘·화력지원형으로 구성되며, 임무에 따라 30mm 또는 40mm 기관포와 105mm 포탑을 장착한다.', specs='{"wheels":8,"rangeKm":1000,"speedKmh":110,"payloadKg":11000,"caliber":40}', image_url='https://international.gdls.com/spanish/images/products/LAV-700-icon.jpg', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='lav-700';
UPDATE weapon_dictionary SET description='Lynx KF41은 라인메탈의 차세대 궤도형 전투차 계열이다. 제조사 제품 페이지는 승무 3명과 병력 8명이 타는 전투실 6.43세제곱미터, Lance 2 포탑의 30mm 기관포와 동축 무장, 선택적 대전차미사일을 제시하고, 헝가리가 2020년 7개 파생형 포함 218대를 계약한 첫 NATO 도입국이며 잘라에게르세그 공장은 2023년 8월에 열렸다.', specs='{"crew":3,"armament":"Lance 2 30mm 기관포, 동축 무장, 선택적 대전차미사일","passengers":8,"interiorVolumeM3":6.43,"caliber":30}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='lynx-kf41';
UPDATE weapon_dictionary SET description='M777은 BAE Systems가 설계하고 제작한 155mm 39구경 경량 견인포다. 자주포가 아니라 차륜으로 견인하는 곡사포이다.', specs='{"caliber":"155mm/39","rangeKm":30,"armament":"155mm 39구경 견인포"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='m777';
UPDATE weapon_dictionary SET description='M92 Vulkan(LRSV-122 M-92)은 크로아티아가 유고슬라비아제 128mm M-77 Oganj 자주 다연장로켓을 122mm Grad 규격 로켓용으로 개조한 체계다. 발사관을 122mm로 바꾸고 발사함과 사격 체계를 고쳤으며, 크로아티아군이 운용하고 NATO 폴란드 전진배치 전투단에도 배치됐다. 슬로보드나 달마시야는 평균 사용 연한이 30년을 넘고 사거리는 20km까지라이다.', specs='{"caliber":"122mm","rangeKm":"20까지"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='m92-vulkan';
UPDATE weapon_dictionary SET description='Marder는 라인메탈 랜드시스템이 개발한 궤도형 보병전투차이다.', specs='{"crew":3,"widthM":3.24,"heightM":2.98,"lengthM":6.79,"rangeKm":520,"weightT":28.5,"armament":"20mm Rheinmetall MK 20 Rh 202, 7.62mm MG3, MILAN 또는 MELLS","speedKmh":65,"passengers":6,"propulsion":"MTU MB 833 Ea-500 디젤"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='marder';
