UPDATE weapon_dictionary SET description='MEKO A-200은 TKMS가 호위함으로 제시하는 함형이며, 하위형은 A-200 SAN, A-200 AN, A-200 EN이다.', specs='{"crew":125,"beamM":16.4,"speed":"29노트 초과","lengthM":121,"aircraft":"6톤급 헬기 2기 또는 11톤급 헬기 1기와 무인기 2기","draughtM":4.4,"embarked":49,"propulsion":"CODAG WARP, 20MW 가스터빈 1기와 센터라인 워터제트, 6MW 디젤 2기와 저소음 가변피치 프로펠러","displacementT":3950,"widthM":16.4,"speedKt":29}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='meko-a200';
