UPDATE weapon_dictionary SET description='모가미급은 일본 해상자위대의 다목적 호위함(FFM)으로, 미쓰비시중공업이 12척을 건조한다. 제원은 기준 배수량 3,900톤, 전장 133m, 폭 16.3m, 최고 속력 약 30노트, 승조원 약 90명이고 Mk 41 수직발사대 16셀을 갖춘다. 2025년 12월 기준으로 8척이 취역했으나 선도함 취역 연도는 이 기사에 없다. 개량형은 선체를 키우고 수직발사대 셀 수를 두 배로 하며, 같은 기사는 2025년 8월 호주가 차기 범용 호위함으로 이 개량형을 선정했다.', specs='{"crew":90,"beamM":16.3,"speed":"약 30노트","lengthM":133,"armament":"Mk 45 Mod 4 5인치포 1문, 12.7mm 원격무장 2문, Mk 41 수직발사대 16셀, SeaRAM 1기, 17식 함대함유도탄 4연장 2기, 기뢰","displacementT":3900,"widthM":16.3}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='mogami-class';
UPDATE weapon_dictionary SET description='Namer는 이스라엘이 Merkava 전차 차체를 바탕으로 만든 궤도형 중장갑 보병전투차다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='namer';
UPDATE weapon_dictionary SET description='프리티오프 난센급은 스페인 Navantia가 Ferrol에서 건조한 노르웨이 해군 호위함이다. 노르웨이군은 다섯 척을 건조해 2011년 1월 마지막 함을 인도했다.', specs='{"crew":120,"beamM":16.8,"lengthM":134,"rangeNm":4500,"speedKt":26,"armament":"ESSM용 수직발사대, NSM, Sting Ray 어뢰, OTO Melara 함포, 폭뢰","draughtM":7.6,"propulsion":"디젤 2기와 가스터빈 1기, 프로펠러 2축","displacementT":5290,"widthM":16.8}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='nansen-class';
