UPDATE weapon_dictionary SET description='Patria CRO 30L은 크로아티아 육군이 운용하는 Patria AMV 8x8 계열 보병전투차 형식이다. 크로아티아 국방부는 2022년 사격 훈련 발표에서 UT30MK2 원격무장에 30mm MK44S Bushmaster II, 7.62mm M240, 스파이크 LR 2연장 발사기를 달았다.', specs='{"armament":"30mm MK44S Bushmaster II, 7.62mm M240, 스파이크 LR 2연장, UT30MK2 원격무장","tubes":2}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='patria-amv';
