UPDATE weapon_dictionary SET description='Pizarro는 스페인에서 제작한 궤도형 보병전투차다. 스페인 육군은 승무원 3명과 보병 7명, 30mm 기관포, 최고속도 70km/h, 항속거리 500km를 공개한다. 현역 총수량은 이번 공식 자료에서 확인하지 못했다.', specs='{"crew":3,"armament":"30mm 기관포, 7.62mm 기관총","speedKmh":70,"caliber":30}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='pizarro';
UPDATE weapon_dictionary SET description='PLZ-45는 Type 88로도 불리는 중국 NORINCO의 155mm 45구경 궤도형 자주포다. 시제차는 1988년 공개됐다. 전투중량 33톤, 승무원 5명, 도로 속도 시속 56km, 항속거리 450km, 크기 6.1m x 3.23m x 2.59m이고 엔진은 Deutz BF12 L413FC 525마력이다.', specs='{"crew":5,"widthM":3.23,"caliber":"155mm/45","heightM":2.59,"lengthM":6.1,"weightT":33,"armament":"155mm/45, 12.7mm 기관총","speedKmh":56,"propulsion":"Deutz BF12 L413FC 525hp"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='plz-45';
