UPDATE weapon_dictionary SET description='PzH 2000은 KNDS Deutschland가 제시하는 155mm L52 궤도형 자주포다. 전투중량 57톤, 전장 11.7m, 전폭 3.5m, 전고 3.4m이고 엔진 출력은 736kW다. 베이스블리드탄 사거리 예는 40km, V-LAP은 최대 54km이며 탄약 60발과 모듈형 장약 288발을 싣고 기본 승무원 3명에 예비 2명을 둔다. KNDS는 2025년 11월 독일, 우크라이나, 크로아티아, 그리스, 헝가리, 이탈리아, 네덜란드, 리투아니아, 카타르가 도입했다.', specs='{"crew":"3+2","widthM":3.5,"caliber":"155mm/L52","heightM":3.4,"lengthM":11.7,"rangeKm":54,"weightT":57,"armament":"155mm/L52, 부무장 기관총","propulsion":"736kW (1,000hp)"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='pzh-2000';
UPDATE weapon_dictionary SET description='Radaa 300은 이집트 아랍산업화기구가 EDEX 2025에서 공개한 궤도형 다연장로켓이다. 개량 ATS-59G 궤도 차체에 중국 노린코 SR5의 자주장전 발사대를 축소해 올렸고, 포드는 1개다. 122mm 로켓 20발, 또는 파이어드래곤 220mm 6발(사거리 25-75km), 300mm 4발(30-150km), 610mm 1발(100-290km)을 실을 수 있고, 전개 2분, 사격명령 대응 5분, 자체 재장전 3분이다.', specs='{"pods":1,"chassis":"개량 ATS-59G 궤도","load122":"122mm 로켓 20발","load220":"220mm 6발, 사거리 25-75km","load300":"300mm 4발, 사거리 30-150km","load610":"610mm 1발, 사거리 100-290km","deployMin":2,"reloadMin":3,"remoteFireM":60,"responseMin":5,"caliber":122}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='radaa-300';
