UPDATE weapon_dictionary SET description='RBS 70은 스웨덴이 개발한 레이저 빔 라이딩 방식의 단거리 지대공미사일 체계다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='rbs-70';
UPDATE weapon_dictionary SET description='RCH 155는 KNDS의 무인 포모듈 AGM을 Boxer 차체에 결합한 155mm L52 원격 조종 자주포다. 발사속도는 분당 8발 초과, V-LAP 사거리는 최대 54km, 전투중량은 40톤 미만이고 승무원 구획은 2명용이다. 영국 국방부는 2026년 5월 영국 육군용 72문을 OCCAR를 통해 KNDS와 라인메탈의 합작사 ARTEC에 계약했다.', specs='{"crew":2,"widthM":2.99,"caliber":"155mm/L52","heightM":3.61,"lengthM":10.5,"rangeKm":54,"armament":"155mm/L52","propulsion":"최대 600kW (815hp)"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='rch-155';
UPDATE weapon_dictionary SET description='리버급은 캐나다 해군이 구축함으로 분류하는 유도탄 구축함으로, 설계는 BAE Systems Type 26에 기반하고 Irving Shipbuilding이 Halifax에서 15척을 건조한다. 캐나다 해군 제원은 배수량 7,800톤, 전장 151.4m, 폭 20.75m, 최고 속력 27노트, 항속거리 7,000해리, 승조 정원 210명이다. 초도함 HMCS Fraser의 본격 생산은 2025년 4월에 시작됐고 초도 인도는 2030년대 초로 예정돼 아직 취역하지 않았다. 이 급은 퇴역한 Iroquois급 구축함과 Halifax급 호위함을 대체한다.', specs='{"crew":210,"beamM":20.75,"lengthM":151.4,"rangeNm":7000,"speedKt":27,"aircraft":"CH-148 Cyclone","armament":"수직발사 미사일, 127mm 주포, 30mm 2문, 경어뢰","displacementT":7800,"widthM":20.75}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='river-class-csc';
UPDATE weapon_dictionary SET description='RM-70은 체코슬로바키아에서 1972년 열병식에 처음 관측된 122mm 다연장로켓으로, NATO 명칭은 M1972이고 현재 코드 CSK는 그 설계 당시의 체코슬로바키아를 가리킨다.', specs='{"crew":6,"tubes":40,"engine":"Tatra T-930-3 V-12 270 hp","reload":"1분 미만","widthM":2.55,"caliber":"122mm","chassis":"Tatra 813 8x8","heightM":2.96,"lengthM":8.8,"salvoSec":"18-22","speedKmh":75,"weightKg":25300,"rocketRangeM":"20000, 최신 모터 36000","spareRockets":40,"vehicleRangeKm":1100}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='rm-70';
UPDATE weapon_dictionary SET description='S-300은 소련이 개발한 장거리 지대공미사일 체계 계열이다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='s-300';
UPDATE weapon_dictionary SET description='S-400 Triumf는 알마즈-안테이의 이동식 장거리 지대공미사일이다.', specs='{"radar91N6ERangeKm":340,"missile40N6RangeKm":"서두 400, 제원표 40N6E 380","missile40N6EAltitudeKm":30}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='s-400';
