UPDATE weapon_dictionary SET description='사르 6급은 독일에서 건조된 이스라엘 해군의 코르벳이다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='saar-6';
UPDATE weapon_dictionary SET description='SIGMA는 네덜란드 Damen이 개발한 모듈형 수상전투함 설계 계열이다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='sigma-damen';
UPDATE weapon_dictionary SET description='Sky Sabre는 영국 육군이 Rapier를 대체하는 지대공미사일 체계다. 영국 육군은 구성품을 Giraffe 레이더, 전투관리체계, Land Ceptor 미사일로 나누고, 레이더는 360도로 120km까지 본다.', specs='{"armament":"CAMM, Land Ceptor 발사대","radarRangeKm":120}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='sky-sabre';
UPDATE weapon_dictionary SET description='9K58 Smerch는 러시아 툴라의 스플라브가 생산하는 300mm 다연장로켓으로, 1980년대 초 개발되어 1988년 러시아군에 취역했다. 발사차는 MAZ-543M 8륜에 12연장, 승무원 4명이고 9M55K 로켓은 길이 7.5m, 중량 800kg 초과, 사거리 20km에서 70km다. 인도는 타트라 차체의 스메르치를 운용하며 2005년 12월 38문을 최초 주문해 2007년 5월부터 2008년에 인도받았다. Tornado-S는 같은 자료가 스메르치를 대체할 별도 개량형으로 구분하므로 이 항목에 합치지 않는다.', specs='{"crew":4,"tubes":12,"rocket":"9M55K","caliber":"300mm","chassis":"MAZ-543M 8x8","rangeKm":"20-70","rocketLengthM":7.5,"rocketWeightKg":"800 초과","lengthM":7.5}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='smerch';
UPDATE weapon_dictionary SET description='소류급은 해상자위대의 재래식 잠수함이다.', specs='{"crew":65,"lengthM":84,"speedKt":20,"armament":"533 mm 발사관 6문, 89식 어뢰, 하푼, 기뢰","propulsion":"디젤-전기, 쇼류까지 스털링 AIP, 오류부터 리튬이온 전지","displacementT":4200}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='soryu-class';
