UPDATE weapon_dictionary SET description='타이게이급은 해상자위대의 재래식 디젤-전기 잠수함으로, 리튬이온 전지로 수중 체류를 늘린 함급이다.', specs='{"lengthM":84,"armament":"18식 어뢰, UGM-84L 하푼","propulsion":"디젤-전기, 리튬이온 전지, 후기함 가와사키 12V 25/31 디젤","displacementT":3000,"widthM":9.1}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='taigei-class';
