UPDATE weapon_dictionary SET description='TOS-1은 소련이 T-72 전차 차체에 열압력 로켓 발사기를 얹은 다연장로켓 체계다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='tos-1';
UPDATE weapon_dictionary SET description='트리덴테급은 포르투갈 해군이 운용하는 재래식 잠수함 두 척으로 구성된다. NRP Tridente는 2010년 취역했으며, 해군은 수중배수량 2,020톤과 길이 67.9m를 공개했다. 포르투갈 해군은 두 함을 Tridente와 Arpão이다.', specs='{"lengthM":67.9,"propulsion":"디젤-전기","displacementT":2020}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='tridente-class';
UPDATE weapon_dictionary SET description='039A/B형 위안급은 중국 인민해방군 해군의 재래식 디젤-전기 잠수함이다.', specs='{"crew":36,"lengthM":77.6,"speedKt":20,"armament":"533 mm 어뢰발사관 6문","propulsion":"Diesel-electric, 1 shaft, AIP","displacementT":3600,"torpedoCaliberMm":533,"torpedoTubes":6}', image_url='https://assets.hiwars.com/assets/7d0720a8-9776-4b7d-bc0e-1a79fdc76f63.webp', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-039a';
