UPDATE weapon_dictionary SET description='209형은 HDW가 수출용으로 개발한 재래식 디젤-전기 잠수함 가족이다.', specs='{"armament":"533 mm 함수 발사관 8문, 어뢰 14발","propulsion":"Diesel-electric, 4 diesels, 1 shaft"}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-209';
UPDATE weapon_dictionary SET description='독일 연방군은 212A형을 비핵 재래식 잠수함으로 보고, 디젤 발전기와 연료전지, 축전지, 전동기를 결합한 외부공기 독립 추진이라고 설명한다. 연방군이다.', specs='{"crew":28,"lengthM":56,"armament":"DM2A4용 어뢰발사관 6문","propulsion":"하이브리드 디젤-전기와 연료전지, 디젤 1기, 전동기 1기, 연료전지 1식, 프로펠러 1, 3100 kW","displacementT":1830,"torpedoTubes":6}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-212a';
UPDATE weapon_dictionary SET description='212CD형은 TKMS가 독일과 노르웨이 해군을 위해 건조하는 재래식 AIP 잠수함으로, 212A의 후속 공동설계다.', specs='{"lengthM":73,"armament":"533 mm 어뢰발사관 6문","propulsion":"디젤-전기, MTU 4000 디젤 2기, PEM 연료전지 AIP, 리튬전지","displacementT":2800}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-212cd';
