UPDATE weapon_dictionary SET description='인빈서블급은 독일 TKMS가 싱가포르 해군을 위해 건조한 218SG형 잠수함이다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-218sg';
UPDATE weapon_dictionary SET description='22형은 영국 해군의 대잠 호위함으로 Broadsword급으로도 불린다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-22';
UPDATE weapon_dictionary SET description='23형 듀크급은 영국 해군의 호위함으로, 왕립해군은 Type 23 또는 Duke급으로 부른다. 원래 대잠전용으로 설계됐고 현재는 다목적 임무에 쓰이며 Inspiration급과 City급으로 대체되는 중이다.', specs='{"est":["beamM","draughtM","propulsion","crew"],"crew":185,"beamM":16.1,"lengthM":133,"rangeNm":7800,"speedKt":28,"armament":"4.5인치 Mk 8 함포, Sea Ceptor 대공미사일, 소구경 기관총","draughtM":7.3,"propulsion":"CODLAG","displacementT":4900}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-23';
UPDATE weapon_dictionary SET description='26형 City급은 영국 해군의 대잠 호위함으로, BAE Systems가 글래스고의 Govan과 Scotstoun에서 8척을 건조한다. 왕립해군 제원은 배수량 6,900톤, 전장 149m, 속력 26노트, 항속거리 7,000해리, 수용 인원 208명이고, 국방장비지원청이다.', specs='{"beamM":20.8,"lengthM":149,"rangeNm":7000,"speedKt":26,"armament":"Sea Ceptor용 수직발사대 12셀, Mk 41 다목적 수직발사대 24셀. Sea Ceptor는 셀당 4발, 함당 48발","propulsion":"전기모터 2기, 고속 디젤 발전기 4기, 가스터빈 직결","accommodation":208,"displacementT":6900,"crew":161,"widthM":20.8}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-26';
UPDATE weapon_dictionary SET description='63식은 중국이 개발한 107mm 12연장 견인식 다연장로켓이다.', specs='{"tubes":12}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-63-mrl';
UPDATE weapon_dictionary SET description='89식 장갑전투차는 육상자위대의 궤도형 보병전투차로, 1980년 개발이 시작되어 1989년 제식화되었다. 육자조사단은 전장 6.80m, 전폭 3.20m, 전고 2.50m, 전비중량 약 26.5톤, 최고속도 약 70km/h, 항속거리 약 400km, 승무 3명과 전투원 7명, 미쓰비시 6SY31WA 수랭 직렬 6기통 터보 디젤 600마력이다.', specs='{"crew":3,"widthM":3.2,"heightM":2.5,"lengthM":6.8,"rangeKm":400,"weightT":26.5,"armament":"오리콘 KDE 35mm 기관포, 74식 7.62mm 동축 기관총, 79식 중MAT 2기","speedKmh":70,"passengers":7,"propulsion":"미쓰비시 6SY31WA 수랭 4행정 직렬 6기통 터보 디젤 600마력","caliber":35}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-89-ifv';
UPDATE weapon_dictionary SET description='영국 국방부는 2026년 6월 방위투자계획에서 Type 83 구축함 계획을 취소하고 Type 45를 대체할 Common Combat Vessel을 최소 6척 개발한다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='uk-ccv';
UPDATE weapon_dictionary SET description='울라급은 노르웨이 해군이 운용하는 재래식 디젤-전기 잠수함으로, Naval Technology는 독일 티센 노르트제베르케가 설계와 건조를 맡고 독일 명칭은 U-Boot-Klasse 210이다.', specs='{"crew":21,"lengthM":59,"speedKt":23,"armament":"533 mm 함수 발사관 8문, Atlas Elektronik DM2A3","propulsion":"MTU 12V 396 디젤 2기 개량형과 전동기, 디젤-전기, 6000 shp","displacementT":1150}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='ula-class';
UPDATE weapon_dictionary SET description='자그레브 대학교 기계공학 및 조선학부 페이지는 스플릿 BSO에서 1983년부터 1988년까지 건조된 포켓 잠수함 가운데 914 Soča가 개조되어 크로아티아 해군 잠수함 Velebit가 되었다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='velebit';
UPDATE weapon_dictionary SET description='2026년 8월 10일 베트남은 다낭의 Song Thu 조선소에서 자체 설계 다목적 호위함 건조 착수 행사를 열었다.', specs='{"caliber":76,"tubes":4}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='vnm-indigenous-frigate';
UPDATE weapon_dictionary SET description='왈루스급은 네덜란드 해군의 디젤-전기 잠수함이다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='walrus';
UPDATE weapon_dictionary SET description='WR-40 Langusta는 후타 스탈로바 볼라가 폴란드 육군용으로 만든 BM-21 개량 다연장로켓이다. 차체는 Jelcz P662D.35-M27 6륜이고 122.4mm 40연장을 올리며, 길이 8.6m, 너비 2.54m, 높이 2.74m, 로켓 제외 중량 17,100kg, 승무원 수용 6명, STANAG 4569 1수준 장갑 운전실이다. 고폭탄 로켓 최대 사거리 42km, 화물탄 32km, 표준 로켓 중량 66.4kg이고 40발을 20초에 발사하며 수동 재장전은 약 7분이다. 이베코 아이포 커서 8 259kW로 도로속도 85km/h, 항속 650km이고, 초도 생산계약은 2006년, 최초 차량 인도는 2007년 3월이다.', specs='{"crew":6,"salvo":"40발, 20초","tubes":40,"engine":"IVECO Aifo Cursor 8, 259 kW","widthM":2.54,"caliber":"122.4mm","chassis":"Jelcz P662D.35-M27 6x6","heightM":2.74,"lengthM":8.6,"speedKmh":85,"weightKg":17100,"heRangeKm":42,"reloadMin":7,"cargoRangeKm":32,"vehicleRangeKm":650,"rangeKm":42}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='wr-40-langusta';
UPDATE weapon_dictionary SET description='WS-1B는 중국 쓰촨의 SAAT가 개발한 302mm Weishi 계열 다연장로켓으로 사거리가 약 180km다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='ws-1b';
UPDATE weapon_dictionary SET description='YPR-765는 네덜란드가 미국제 Improved M113, 곧 AIFV를 바탕으로 도입한 궤도형 보병전투차다. 국방 잡지 마테리얼헤진은 1975년 889대 최초 발주가 프랑스제 AMX VCI 대체를 위한 것이었고, 보병형과 지휘형은 25mm 외를리콘 속사포를, 다른 형은 브라우닝 12.7mm 기관총이나 무장을 쓰지 않는다.', specs='{"widthM":2.82,"lengthM":5.26,"weightT":13.5,"armament":"보병형과 지휘형은 25mm Oerlikon, 그 외 Browning 12.7mm 또는 비무장, 대전차형은 TOW","speedKmh":70,"propulsion":"6기통 4행정 디젤 191kW (265hp)","emptyWeightKg":12000}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='ypr-765';
UPDATE weapon_dictionary SET description='Zuzana는 슬로바키아가 개발한 155mm 차륜형 자주곡사포다.', specs='{}', image_url=NULL, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='zuzana';
